values.headerSass:
.custom-header {
  .usgsHeader {
  background-color:#253f60;
}

.PGMtitle {
  background-color:#001028;
  color:#ffffff;
  font-size:20px;
  padding:10px 10px 10px 10px;
}

.navbar, .navbar-default, .navbar-header, .navbar-toggle, .icon-bar, .collapse, .navbar-collapse, .nav, .navbar-nav, .navbar-right {
  position:relative;
}








.dropdown-submenu {
    position: relative;
}

.dropdown-submenu>.dropdown-menu {
    top: 0;
    left: 100%;
    margin-top: -6px;
    margin-left: -1px;
    -webkit-border-radius: 0 6px 6px 6px;
    -moz-border-radius: 0 6px 6px;
    border-radius: 0 6px 6px 6px;
}

.dropdown-submenu:hover>.dropdown-menu {
    display: block;
}

.dropdown-submenu>a:after {
    display: block;
    content: " ";
    float: right;
    width: 0;
    height: 0;
    border-color: transparent;
    border-style: solid;
    border-width: 5px 0 5px 5px;
    border-left-color: #ccc;
    margin-top: 5px;
    margin-right: -10px;
}

.dropdown-submenu:hover>a:after {
    border-left-color: #fff;
}

.dropdown-submenu.pull-left {
    float: none;
}

.dropdown-submenu.pull-left>.dropdown-menu {
    left: -100%;
    margin-left: 10px;
    -webkit-border-radius: 6px 0 6px 6px;
    -moz-border-radius: 6px 0 6px 6px;
    border-radius: 6px 0 6px 6px;
}

  }

values.footerSass:
.custom-footer {
  			body,html{
				margin: 0;
				padding: 0;
				font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol";
			}

			#usgsBar{
				display: block;
				width: 100%;
				box-sizing: border-box;
				padding: 15px 25px;
				background-color: #02274b;
			}

			nav#main{
				display: flex;
				box-sizing: border-box;
				padding: 8px 25px;
				gap: 30px;
				margin-bottom: 45px;
				flex-wrap: wrap;
			}
				nav#main .branding{
					flex-grow: 3;
					box-sizing: border-box;
				}
					nav#main .branding .logo{
					}
				nav#main .nav-link{
					display: flex;
					flex-direction: column;
					justify-content: center;
					color: black;
					text-decoration: none;
					font-weight: 600;
					font-size: 14px;
				}
					nav#main .nav-link:focus{
						text-decoration: underline;
					}
					nav#main .nav-link:hover{
						text-decoration: underline;
						color: #0d6eff;
					}
			
			/* Main content */
			.page-body{
				display: block;
				max-width: 600px;
				margin: 0 auto;
				box-sizing: border-box;
				padding: 15px;
				min-height: 80vh;
				min-height: calc(100vh - 209px);
			}
			h1{
				font-size: 34px;
			}
			p{
				font-size: 16px;
				line-height: 28px;
				padding: 15px 0;
			}

			/* USGS Footer */
			footer#usgs{
				background-color: #02274b;
				box-sizing: border-box;
				padding: 8px 10px;
			}
				footer#usgs a{
					color: white;
					font-size: 12px;
					margin-right: 18px;
					position: relative;
					text-decoration: none;
				}

			/* Button Styles */
			button,
			.button{
				background-color: #02274b;
				color: white;
				display: inline-block;
				padding: 10px 20px;
				border-radius: 5px;
				text-decoration: none;
				font-size: 16px;
				font-weight: 500;
				letter-spacing: 0.3px;
			}
			.button:focus,
			button:focus{
				text-decoration: underline;
			}
			.button:hover,
			button:hover{
				text-decoration: underline;
				background-color: #001a33;
			}
  }
